create table RB_BUS_VOUCHER_ACCT_RELATION (CARD_NO VARCHAR(19) null  ,VOUCHER_NO VARCHAR(60) not null  ,ACCT_SEQ_NO VARCHAR(5) null  ,ACCT_CCY VARCHAR(3) null  ,TRAN_DATE TIMESTAMP(3) null  ,COLLAT_IND VARCHAR(1) null  ,DOC_TYPE VARCHAR(4) not null  ,NARRATIVE VARCHAR(600) null  ,DOC_CLASS VARCHAR(3) null  ,CREATE_TIMESTAMP VARCHAR(26) not null  ,LAST_UPD_TIMESTAMP VARCHAR(26) not null  ,OLD_STATUS VARCHAR(3) not null  ,COLLAT_NO VARCHAR(100) null  ,PROD_NO VARCHAR(20) null  ,PREFIX VARCHAR(10) null  ,BASE_ACCT_NO VARCHAR(50) not null  ,CAN_REASON_CODE VARCHAR(2) null  ,REFERENCE VARCHAR(60) null  ,VOUCHER_STATUS VARCHAR(3) not null  , primary key(VOUCHER_NO,DOC_TYPE,BASE_ACCT_NO));